-- RTF-038 reconciliation distributed claim columns
ALTER TABLE cpf_unknown_result
    ADD COLUMN attempt_count INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN next_check_at TIMESTAMP(3) NULL,
    ADD COLUMN lease_owner VARCHAR(120) NULL,
    ADD COLUMN lease_until TIMESTAMP(3) NULL,
    ADD COLUMN row_version BIGINT NOT NULL DEFAULT 0;
CREATE INDEX ix_cpf_unknown_result_claim ON cpf_unknown_result (unknown_status, next_check_at, lease_until, detected_at);

-- CPF Enterprise QA V64 - Runtime Control Plane (PostgreSQL)
ALTER TABLE cpf_service ADD COLUMN row_version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE cpf_service_endpoint ADD COLUMN row_version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE cpf_service_instance ADD COLUMN environment_code VARCHAR(40) NOT NULL DEFAULT 'default';
ALTER TABLE cpf_service_instance ADD COLUMN zone_code VARCHAR(60);
ALTER TABLE cpf_service_instance ADD COLUMN cell_code VARCHAR(60);
ALTER TABLE cpf_service_instance ADD COLUMN priority_no INTEGER NOT NULL DEFAULT 100;
ALTER TABLE cpf_service_instance ADD COLUMN maintenance_yn CHAR(1) NOT NULL DEFAULT 'N';
ALTER TABLE cpf_service_instance ADD COLUMN drain_yn CHAR(1) NOT NULL DEFAULT 'N';
ALTER TABLE cpf_service_instance ADD COLUMN drain_deadline_at TIMESTAMP(3);
ALTER TABLE cpf_service_instance ADD COLUMN row_version BIGINT NOT NULL DEFAULT 0;
CREATE INDEX ix_cpf_service_instance_placement ON cpf_service_instance(environment_code,zone_code,cell_code,active_yn,instance_status);
CREATE INDEX ix_cpf_service_instance_route ON cpf_service_instance(endpoint_code,priority_no,maintenance_yn,drain_yn,active_yn,instance_status);
ALTER TABLE cpf_service_instance ADD CONSTRAINT ck_cpf_service_instance_maintenance CHECK(maintenance_yn IN ('Y','N'));
ALTER TABLE cpf_service_instance ADD CONSTRAINT ck_cpf_service_instance_drain CHECK(drain_yn IN ('Y','N'));

CREATE TABLE cpf_runtime_version(version_key VARCHAR(40) PRIMARY KEY,version_no BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO cpf_runtime_version(version_key,version_no) VALUES('GLOBAL',0);

CREATE TABLE cpf_runtime_controller_lease(lease_key VARCHAR(60) PRIMARY KEY,holder_id VARCHAR(120) NOT NULL,fencing_token BIGINT NOT NULL DEFAULT 0,lease_until TIMESTAMP(3) NOT NULL,last_reconciled_at TIMESTAMP(3),created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_cpf_runtime_controller_lease_until ON cpf_runtime_controller_lease(lease_until);

CREATE TABLE cpf_runtime_rate_bucket(bucket_key VARCHAR(180) PRIMARY KEY,subject_id VARCHAR(120) NOT NULL,window_start TIMESTAMP(3) NOT NULL,request_count INTEGER NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT ck_cpf_runtime_rate_count CHECK(request_count >= 0));
CREATE INDEX ix_cpf_runtime_rate_subject ON cpf_runtime_rate_bucket(subject_id,window_start);


CREATE TABLE cpf_runtime_instance_group(group_id VARCHAR(80) PRIMARY KEY,group_name VARCHAR(150) NOT NULL,parent_group_id VARCHAR(80),environment_code VARCHAR(40),description VARCHAR(500),active_yn CHAR(1) NOT NULL DEFAULT 'Y',row_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_cpf_runtime_group_parent FOREIGN KEY(parent_group_id) REFERENCES cpf_runtime_instance_group(group_id),CONSTRAINT ck_cpf_runtime_group_active CHECK(active_yn IN ('Y','N')));
CREATE INDEX ix_cpf_runtime_group_parent ON cpf_runtime_instance_group(parent_group_id,active_yn); CREATE INDEX ix_cpf_runtime_group_env ON cpf_runtime_instance_group(environment_code,active_yn);
CREATE TABLE cpf_runtime_group_member(group_id VARCHAR(80) NOT NULL,instance_id VARCHAR(120) NOT NULL,active_yn CHAR(1) NOT NULL DEFAULT 'Y',created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(group_id,instance_id),CONSTRAINT fk_cpf_runtime_group_member_group FOREIGN KEY(group_id) REFERENCES cpf_runtime_instance_group(group_id) ON DELETE CASCADE,CONSTRAINT fk_cpf_runtime_group_member_instance FOREIGN KEY(instance_id) REFERENCES cpf_service_instance(instance_id) ON DELETE CASCADE,CONSTRAINT ck_cpf_runtime_group_member_active CHECK(active_yn IN ('Y','N')));
CREATE INDEX ix_cpf_runtime_group_member_instance ON cpf_runtime_group_member(instance_id,active_yn);
CREATE TABLE cpf_runtime_instance_state(instance_id VARCHAR(120) PRIMARY KEY,fencing_token BIGINT NOT NULL DEFAULT 0,lease_until TIMESTAMP(3),desired_version BIGINT NOT NULL DEFAULT 0,actual_version BIGINT NOT NULL DEFAULT 0,desired_hash VARCHAR(64),actual_hash VARCHAR(64),drift_state VARCHAR(30) NOT NULL DEFAULT 'IN_SYNC',capabilities_json TEXT,labels_json TEXT,artifact_version VARCHAR(100),artifact_commit VARCHAR(64),runtime_role VARCHAR(40),registration_source VARCHAR(120),schema_version VARCHAR(100),config_hash VARCHAR(64),clock_skew_ms BIGINT NOT NULL DEFAULT 0,last_ack_change_id VARCHAR(80),last_ack_at TIMESTAMP(3),heartbeat_at TIMESTAMP(3),created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_cpf_runtime_instance_state_instance FOREIGN KEY(instance_id) REFERENCES cpf_service_instance(instance_id) ON DELETE CASCADE,CONSTRAINT ck_cpf_runtime_instance_drift CHECK(drift_state IN ('IN_SYNC','PENDING','DRIFT','UNKNOWN','UNKNOWN_RESULT','PENDING_RESTART','EXCLUDED')));
CREATE INDEX ix_cpf_runtime_instance_lease ON cpf_runtime_instance_state(lease_until); CREATE INDEX ix_cpf_runtime_instance_drift ON cpf_runtime_instance_state(drift_state,heartbeat_at);

CREATE TABLE cpf_runtime_instance_feature_state(instance_id VARCHAR(120) NOT NULL,change_type VARCHAR(80) NOT NULL,desired_version BIGINT NOT NULL DEFAULT 0,actual_version BIGINT NOT NULL DEFAULT 0,desired_hash VARCHAR(64),actual_hash VARCHAR(64),drift_state VARCHAR(30) NOT NULL DEFAULT 'UNKNOWN',source_delivery_id VARCHAR(80),created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(instance_id,change_type),CONSTRAINT fk_cpf_runtime_feature_instance FOREIGN KEY(instance_id) REFERENCES cpf_service_instance(instance_id) ON DELETE CASCADE,CONSTRAINT ck_cpf_runtime_feature_drift CHECK(drift_state IN ('IN_SYNC','PENDING','DRIFT','UNKNOWN','UNKNOWN_RESULT','PENDING_RESTART','EXCLUDED')));
CREATE INDEX ix_cpf_runtime_feature_drift ON cpf_runtime_instance_feature_state(drift_state,change_type);
CREATE INDEX ix_cpf_runtime_feature_delivery ON cpf_runtime_instance_feature_state(source_delivery_id);

CREATE TABLE cpf_control_operation(operation_id VARCHAR(100) PRIMARY KEY,command_type VARCHAR(80) NOT NULL,request_hash VARCHAR(64) NOT NULL,entity_id VARCHAR(100),result_state VARCHAR(30) NOT NULL DEFAULT 'PROCESSING',result_json TEXT,expires_at TIMESTAMP(3),created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT ck_cpf_control_operation_state CHECK(result_state IN ('PROCESSING','SUCCESS','FAILED','UNKNOWN','EXPIRED','CANCELLED')));
CREATE INDEX ix_cpf_control_operation_expiry ON cpf_control_operation(result_state,expires_at);
CREATE TABLE cpf_runtime_change(change_id VARCHAR(80) PRIMARY KEY,operation_id VARCHAR(100) NOT NULL UNIQUE,change_type VARCHAR(80) NOT NULL,payload_schema_version INTEGER NOT NULL DEFAULT 1,request_hash VARCHAR(64) NOT NULL,payload_hash VARCHAR(64) NOT NULL,payload_json TEXT NOT NULL,rollback_payload_json TEXT,target_snapshot_json TEXT NOT NULL,desired_version BIGINT NOT NULL,rollout_mode VARCHAR(30) NOT NULL DEFAULT 'ALL_AT_ONCE',wave_size INTEGER NOT NULL DEFAULT 100,quorum_percent INTEGER NOT NULL DEFAULT 100,change_state VARCHAR(30) NOT NULL DEFAULT 'APPLYING',scheduled_at TIMESTAMP(3),expires_at TIMESTAMP(3),reason VARCHAR(1000) NOT NULL,approval_id VARCHAR(100),break_glass_id VARCHAR(100),requested_by VARCHAR(100) NOT NULL,created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_cpf_runtime_change_operation FOREIGN KEY(operation_id) REFERENCES cpf_control_operation(operation_id),CONSTRAINT ck_cpf_runtime_change_state CHECK(change_state IN ('SCHEDULED','APPLYING','PARTIAL','SUCCESS','FAILED','CANCELLED','EXPIRED','ROLLBACK_PENDING','ROLLED_BACK','SUPERSEDED','UNKNOWN_RESULT','RECOVERED')));
CREATE INDEX ix_cpf_runtime_change_state ON cpf_runtime_change(change_state,scheduled_at,expires_at);
CREATE TABLE cpf_runtime_delivery(delivery_id VARCHAR(80) PRIMARY KEY,change_id VARCHAR(80) NOT NULL,instance_id VARCHAR(120) NOT NULL,sequence_no INTEGER NOT NULL,desired_version BIGINT NOT NULL,delivery_state VARCHAR(30) NOT NULL DEFAULT 'PENDING',attempt_no INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,fencing_token BIGINT,claimed_at TIMESTAMP(3),acknowledged_at TIMESTAMP(3),actual_hash VARCHAR(64),error_code VARCHAR(80),error_message VARCHAR(900),created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_cpf_runtime_delivery_change FOREIGN KEY(change_id) REFERENCES cpf_runtime_change(change_id) ON DELETE CASCADE,CONSTRAINT fk_cpf_runtime_delivery_instance FOREIGN KEY(instance_id) REFERENCES cpf_service_instance(instance_id) ON DELETE CASCADE,CONSTRAINT ck_cpf_runtime_delivery_state CHECK(delivery_state IN ('PENDING','CLAIMED','ACKED','FAILED','POISONED','UNKNOWN_RESULT','RESTART_REQUIRED','CANCELLED','EXPIRED','SUPERSEDED')));
CREATE INDEX ix_cpf_runtime_delivery_claim ON cpf_runtime_delivery(instance_id,delivery_state,next_attempt_at,sequence_no); CREATE INDEX ix_cpf_runtime_delivery_change ON cpf_runtime_delivery(change_id,delivery_state);
CREATE TABLE cpf_runtime_change_audit(audit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,change_id VARCHAR(80) NOT NULL,event_type VARCHAR(60) NOT NULL,actor_id VARCHAR(100) NOT NULL,reason VARCHAR(500),evidence_hash VARCHAR(64),previous_hash VARCHAR(64) NOT NULL,chain_hash VARCHAR(64) NOT NULL,created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_cpf_runtime_audit_change FOREIGN KEY(change_id) REFERENCES cpf_runtime_change(change_id) ON DELETE CASCADE);
CREATE INDEX ix_cpf_runtime_change_audit_change ON cpf_runtime_change_audit(change_id,audit_id);
CREATE TABLE cpf_cache_refresh_checkpoint(consumer_id VARCHAR(120) PRIMARY KEY,last_event_id BIGINT NOT NULL DEFAULT 0,last_applied_at TIMESTAMP(3),created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ix_cpf_cache_refresh_checkpoint_event ON cpf_cache_refresh_checkpoint(last_event_id);
